  have h_order_preserving : ∀ x y : α, x ≤ y → f x ≤ f y :=
    OrderRingHom.orderPreserving f
  have h_additive : ∀ x y : α, f (x + y) = f x + f y :=
    OrderRingHom.add f
  have h_multiplicative : ∀ x y : α, f (x * y) = f x * f y :=
    OrderRingHom.mul f
